const zakatHeaders={zakat_people:['Nama Lengkap','Jenis Jamaah','Asnaf','Nama RT','Anggota Keluarga','Telepon','Alamat'],zakat_entries:['Tanggal','ID Jamaah','Arus','Jenis Zakat','Uang (Rp)','Beras (kg)','Jumlah Jiwa','Catatan']};
function downloadZakatTemplate(){const t=section;const instructions=t==='zakat_people'?[['Jenis Jamaah','muzakki atau mustahik'],['Asnaf','Wajib untuk mustahik: '+asnaf.join(', ')],['Nama RT','Wajib untuk mustahik'],['Anggota Keluarga','Bilangan bulat minimal 1']]:[['Tanggal','Teks YYYY-MM-DD, contoh 2026-11-06'],['ID Jamaah','Salin ID dari sheet Referensi Jamaah'],['Arus','penerimaan atau penyaluran'],['Jenis Zakat','fitrah atau mal'],['Nilai','Uang atau beras harus lebih dari 0; mal hanya uang'],['Jumlah Jiwa','Bilangan bulat minimal 1']];const sheets=[{name:'Data',rows:[zakatHeaders[t]]},{name:'Petunjuk',rows:[['Aturan','Keterangan'],['Impor','Menambah data baru, bukan memperbarui data lama. Maksimal 1000 baris / 2 MB.'],['Isi','Isi sheet Data mulai baris 2. Jangan ubah judul kolom. Angka tanpa Rp atau pemisah ribuan.'],['Formula','Gunakan nilai langsung, bukan formula.'],...instructions]}];if(t==='zakat_entries')sheets.push({name:'Referensi Jamaah',rows:[['ID Jamaah','Nama','Jenis'],...db.zakat_people.map(p=>[p.id,p.full_name,p.person_type])]});downloadBlob(SimasExport.xlsx(sheets),'Template-'+t+'.xlsx')}
function parseZakatRows(matrix,t){const errors=[],records=[],seen=new Set();const norm=v=>String(v??'').trim();if(JSON.stringify((matrix[0]||[]).map(norm))!==JSON.stringify(zakatHeaders[t]))return {records,errors:['Judul kolom tidak sesuai. Gunakan Download Template pada tab ini.']};if(matrix.length>1001)return {records,errors:['Maksimal 1000 baris per impor.']};const text=(v,label,max,required=false)=>{v=norm(v);if(required&&!v)throw Error(label+' wajib diisi');if(v.length>max)throw Error(label+' terlalu panjang');return v};const num=(v,label,min,max,integer=false)=>{if(norm(v)===''||!/^\d+(\.\d+)?$/.test(norm(v)))throw Error(label+' harus angka tanpa pemisah ribuan');let n=Number(v);if(!Number.isFinite(n)||n<min||n>max||(integer&&!Number.isInteger(n)))throw Error(label+' di luar batas');return n};for(let i=1;i<matrix.length;i++){let a=matrix[i];if(a.every(v=>!norm(v)))continue;try{if(a.length>zakatHeaders[t].length&&a.slice(zakatHeaders[t].length).some(v=>norm(v)))throw Error('Ada kolom tambahan');let d;if(t==='zakat_people'){d={full_name:text(a[0],'Nama',150,true),person_type:norm(a[1]).toLowerCase(),asnaf:norm(a[2]).toLowerCase()||null,rt_name:text(a[3],'Nama RT',100)||null,household:num(a[4],'Anggota keluarga',1,100000,true),phone:text(a[5],'Telepon',40),address:text(a[6],'Alamat',500)};if(d.full_name.length<2)throw Error('Nama minimal 2 karakter');if(!['muzakki','mustahik'].includes(d.person_type))throw Error('Jenis jamaah harus muzakki / mustahik');if(d.person_type==='mustahik'&&(!asnaf.includes(d.asnaf)||!d.rt_name))throw Error('Mustahik wajib mempunyai asnaf yang valid dan Nama RT');if(d.person_type==='muzakki'){d.asnaf=null;d.rt_name=null}const key=d.person_type+'|'+d.full_name.toLowerCase();if(seen.has(key)||db.zakat_people.some(p=>p.person_type===d.person_type&&p.full_name.toLowerCase()===d.full_name.toLowerCase()))throw Error('Nama dan jenis jamaah sudah ada. Periksa data sebelum menambah duplikat.');seen.add(key)}else{let day=a[0];if(typeof day==='number'){const date=XLSX.SSF.parse_date_code(day);if(!date)throw Error('Tanggal Excel tidak valid');day=`${date.y}-${String(date.m).padStart(2,'0')}-${String(date.d).padStart(2,'0')}`}day=norm(day);if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!Number.isFinite(Date.parse(day))||new Date(day).toISOString().slice(0,10)!==day)throw Error('Tanggal harus YYYY-MM-DD dan valid');const directions={penerimaan:'receipt',penyaluran:'distribution',receipt:'receipt',distribution:'distribution'};d={occurred_on:day,party_id:norm(a[1]),direction:directions[norm(a[2]).toLowerCase()],zakat_type:norm(a[3]).toLowerCase().replace(/^zakat\s+/,''),amount:num(a[4],'Uang',0,999999999999),rice_kg:num(a[5],'Beras',0,999999999),people_count:num(a[6],'Jumlah jiwa',1,100000,true),notes:text(a[7],'Catatan',1000)};if(d.zakat_type==='mall')d.zakat_type='mal';if(!d.direction||!['fitrah','mal'].includes(d.zakat_type))throw Error('Arus atau jenis zakat tidak valid');d.party_role=d.direction==='receipt'?'muzakki':'mustahik';if(!db.zakat_people.some(p=>p.id===d.party_id&&p.person_type===d.party_role))throw Error('ID jamaah tidak ditemukan atau jenis jamaah tidak cocok dengan arus');if(d.amount<=0&&d.rice_kg<=0)throw Error('Isi uang atau beras lebih dari nol');if(d.zakat_type==='mal'&&d.rice_kg>0)throw Error('Zakat mal hanya dicatat dalam uang');if(Math.abs(d.amount*100-Math.round(d.amount*100))>0.0001||Math.abs(d.rice_kg*1000-Math.round(d.rice_kg*1000))>0.0001)throw Error('Uang maksimal 2 desimal; beras maksimal 3 desimal');const key=JSON.stringify(d);if(seen.has(key)||db.zakat_entries.some(r=>Object.keys(d).every(k=>String(r[k]??'')===String(d[k]??''))))throw Error('Transaksi identik sudah ada. Periksa agar tidak terimpor dua kali.');seen.add(key)}records.push(d)}catch(err){errors.push('Baris '+(i+1)+': '+err.message)}}if(!records.length&&!errors.length)errors.push('Sheet Data belum berisi data.');return {records,errors}}
function openZakatImport(){const t=section;if(!moduleEdit()||moduleError)return;uiDialog('Import Excel · '+tableNames[t],'<p class="dialog-hint">Gunakan template dari tab ini. Semua baris diperiksa sebelum disimpan. Maksimal 1000 baris, 2 MB.</p><label>Pilih berkas Excel (.xlsx)<input id="import-file" type="file" accept=".xlsx"></label><div id="import-result" aria-live="polite"></div><button id="import-save" class="primary" disabled>Simpan hasil impor</button>');let ready=[];const fileInput=$('#import-file'),result=$('#import-result'),saveButton=$('#import-save');fileInput.onchange=async()=>{ready=[];saveButton.disabled=true;const file=fileInput.files[0];if(!file)return;try{if(file.size>2*1024*1024||!/\.xlsx$/i.test(file.name))throw Error('Pilih berkas .xlsx berukuran maksimal 2 MB.');const book=XLSX.read(await file.arrayBuffer(),{type:'array',sheetRows:1002,cellFormula:true});const sheet=book.Sheets.Data;if(!sheet)throw Error('Sheet Data tidak ditemukan.');if(Object.entries(sheet).some(([k,v])=>!k.startsWith('!')&&v.f))throw Error('Formula tidak diperbolehkan. Tempel sebagai nilai terlebih dahulu.');const parsed=parseZakatRows(XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true,blankrows:true}),t);ready=parsed.records;result.innerHTML=`<p><strong>${ready.length} baris valid</strong> · ${parsed.errors.length} kesalahan</p>${parsed.errors.length?'<ul class="import-errors">'+parsed.errors.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ul><p>Perbaiki berkas, lalu pilih ulang. Belum ada data disimpan.</p>':''}<div class="import-preview">${plainTable(reportRows(t,ready.slice(0,20)))}</div><p>Pratinjau menampilkan maksimal 20 baris.</p>`;saveButton.disabled=!!parsed.errors.length||!ready.length}catch(err){result.textContent=err.message}};saveButton.onclick=async()=>{saveButton.disabled=true;fileInput.disabled=true;try{if(!moduleEdit()||moduleError)throw Error('Akses berubah. Muat ulang halaman.');if(live){const rows=await api('/rest/v1/'+t,{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(ready.map(r=>({...r,mosque_id:mosque.id})))});if(!rows||rows.length!==ready.length)throw Error('Jumlah hasil tidak sesuai. Periksa daftar sebelum mengulang impor.');await loadModules()}else{const updated=[...ready.map(r=>({...r,id:crypto.randomUUID(),created_at:new Date().toISOString()})),...db[t]];localStorage.setItem('simas-demo',JSON.stringify({...db,[t]:updated}));db[t]=updated}$('#ui-dialog').close();render();toast('✓ '+ready.length+' baris berhasil diimpor')}catch(err){result.textContent=err.message+' — Periksa daftar data sebelum mencoba lagi.';fileInput.disabled=false;ready=[]}}}
const inputSettings=settings;settings=()=>inputSettings()+`<section class="panel settings-panel"><h3>Pembaruan input & rekap qurban</h3><p>Jalankan migrasi ini setelah migrasi zakat & qurban untuk mengaktifkan Nama RT, jenis qurban, tahun, dan nominal peserta di Supabase.</p><a class="secondary" href="downloads/20261106_input_updates.sql" download>↓ Unduh pembaruan SQL</a></section>`;

// Dashboard: independent funds and calendar-year aggregation, never mixed units.
const dashboardArrow='<svg class="dashboard-arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
const dashboardYear=new Date().getFullYear();
const dashboardRanges={zakat:{from:dashboardYear-4,to:dashboardYear},qurban:{from:dashboardYear-4,to:dashboardYear}};
function annualFundRows(kind,from,to){
 const rows=Array.from({length:to-from+1},(_,i)=>({year:from+i,income:0,expense:0}));
 const source=kind==='zakat'?(db.zakat_entries||[]):qurbanCashRows();
 source.forEach(r=>{const year=kind==='zakat'?Number((r.occurred_on||'').slice(0,4)):Number(r.year);if(year<from||year>to||!Number.isInteger(year))return;const side=kind==='zakat'?(r.direction==='receipt'?'income':'expense'):r.kind;if(side==='income'||side==='expense')rows[year-from][side]+=Number(r.amount)||0});
 return rows;
}
function fundChart(kind){
 const range=dashboardRanges[kind],rows=annualFundRows(kind,range.from,range.to),incoming=rows.reduce((s,r)=>s+r.income,0),outgoing=rows.reduce((s,r)=>s+r.expense,0),max=Math.max(1,...rows.flatMap(r=>[r.income,r.expense]));
 const label=kind==='zakat'?'Zakat':'Qurban',compact=n=>new Intl.NumberFormat('id-ID',{notation:'compact',maximumFractionDigits:1}).format(n);
 const svg=`<svg class="fund-svg" viewBox="0 0 600 240" role="img" aria-label="Grafik penerimaan dan penyaluran dana ${label} per tahun. Rincian tersedia pada tabel di bawah.">${[0,.5,1].map(v=>`<line x1="58" x2="584" y1="${194-v*162}" y2="${194-v*162}" stroke="#e4e9e1" stroke-dasharray="4 5"/><text x="48" y="${198-v*162}" text-anchor="end">${compact(max*v)}</text>`).join('')}${rows.map((r,i)=>{const step=526/rows.length,cx=58+step*(i+.5),w=Math.min(23,step*.28);return `<g>${['income','expense'].map((s,j)=>`<rect x="${cx+(j?3:-w-3)}" y="${194-r[s]/max*162}" width="${w}" height="${r[s]/max*162}" rx="3" fill="${j?'#c4a450':'#3f7e65'}"><title>${r.year} · ${j?'Penyaluran':'Penerimaan'}: ${money(r[s])}</title></rect>`).join('')}<text x="${cx}" y="217" text-anchor="middle">${r.year}</text></g>`}).join('')}</svg>`;
 return `<div class="fund-chart-content" aria-live="polite"><div class="fund-chart-totals"><div><small><i class="chart-dot"></i>Penerimaan</small><strong>${money(incoming)}</strong></div><div><small><i class="chart-dot out"></i>Penyaluran dana</small><strong>${money(outgoing)}</strong></div></div><div class="fund-plot">${incoming||outgoing?svg:'<div class="chart-empty"><span>Belum ada transaksi dana</span><p>Pilih rentang tahun lain atau catat transaksi baru.</p></div>'}</div><p class="chart-footnote">${kind==='zakat'?'Dana fitrah & mal dalam rupiah. Beras dicatat terpisah dalam kg.':'Penerimaan termasuk nominal Shohibul Qurban. Penyaluran dana = pengeluaran kas; daging dicatat terpisah dalam kg.'}</p><details class="chart-details"><summary>Lihat rincian per tahun</summary><div class="table-wrap"><table><thead><tr><th>Tahun</th><th>Penerimaan</th><th>Penyaluran dana</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.year}</td><td>${money(r.income)}</td><td>${money(r.expense)}</td></tr>`).join('')}</tbody></table></div></details></div>`;
}
function fundChartPanel(kind){const range=dashboardRanges[kind],label=kind==='zakat'?'Zakat':'Qurban';return `<section class="panel fund-chart"><div class="panel-head"><div><div class="dashboard-eyebrow">ARUS DANA TAHUNAN</div><h3>Penerimaan & penyaluran ${label.toLowerCase()}</h3></div></div><form class="year-range" data-fund-range="${kind}"><label>Dari tahun<input name="from" aria-label="Tahun awal grafik ${label}" type="number" min="2000" max="2200" value="${range.from}" required></label><span>—</span><label>Sampai tahun<input name="to" aria-label="Tahun akhir grafik ${label}" type="number" min="2000" max="2200" value="${range.to}" required></label><button class="secondary" type="submit">Terapkan</button><p class="range-error" role="alert"></p></form><div id="chart-${kind}">${fundChart(kind)}</div></section>`}
function bindDashboard(){document.querySelectorAll('[data-fund-range]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const from=Number(f.elements.from.value),to=Number(f.elements.to.value),error=f.querySelector('.range-error');if(!Number.isInteger(from)||!Number.isInteger(to)||from<2000||to>2200||from>to||to-from>19){error.textContent='Pilih tahun 2000–2200, urutan awal ≤ akhir, maksimal 20 tahun.';return}error.textContent='';dashboardRanges[f.dataset.fundRange]={from,to};$('#chart-'+f.dataset.fundRange).innerHTML=fundChart(f.dataset.fundRange)})}
function fundSummary(kind,v){const z=kind==='zakat',incoming=z?v.zIn:v.qIn,outgoing=z?v.zOut:v.qOut;return `<section class="fund-summary ${z?'':'qurban-summary-card'}"><div class="fund-summary-top"><span class="fund-icon">${z?'♡':'◇'}</span><div><h3>${z?'Dana zakat':'Kas qurban'}</h3><small>Tahun kegiatan ${dashboardYear}</small></div><button class="link" data-page="${kind}" aria-label="Buka menu ${kind}">${dashboardArrow}</button></div><div class="fund-balance"><small>Saldo ${z?'dana':'kas'}</small><strong>${money(incoming-outgoing)}</strong></div><div class="fund-split"><div><small>Penerimaan</small><b>${money(incoming)}</b></div><div><small>Penyaluran dana</small><b>${money(outgoing)}</b></div></div><p class="fund-note">${z?`Beras diterima <b>${fmt(v.riceIn)} kg</b> · disalurkan <b>${fmt(v.riceOut)} kg</b>`:`Daging diserahkan <b>${fmt(v.kg)} kg</b> · <b>${v.collected}/${v.coupons}</b> distribusi selesai`}</p></section>`}
dashboard=()=>{const s=sums(),fin=['admin','takmir','bendahara'].includes(role),ev=db.events.filter(e=>new Date(e.starts_at)>=new Date()).sort((a,b)=>a.starts_at.localeCompare(b.starts_at)),v=allowedModule()?totals(dashboardYear):null;return top('Ringkasan masjid','Assalamu’alaikum. Pantau amanah dan kegiatan masjid dalam satu ruang.',`<div class="date">◷ &nbsp; ${date(new Date())}</div>`)+`<section class="finance-headline"><div class="headline-top"><span class="headline-label"><i></i> KEUANGAN UTAMA · KAS UMUM</span><span class="headline-period">Akumulasi seluruh transaksi</span></div><div class="headline-main"><div><p>Saldo kas masjid</p><h2>${fin?money(s.balance):'Akses terbatas'}</h2><span>Dana zakat dan qurban dikelola secara terpisah.</span></div><button class="headline-link" data-page="keuangan">Lihat keuangan ${dashboardArrow}</button></div><div class="headline-metrics"><div><small>Total pemasukan</small><strong>${fin?money(s.income):'Terbatas'}</strong><span>Seluruh dana kas yang diterima</span></div><div><small>Total pengeluaran</small><strong>${fin?money(s.expense):'Terbatas'}</strong><span>Operasional & kemakmuran masjid</span></div><div><small>▦ Agenda mendatang</small><strong>${ev.length} <em>kegiatan</em></strong><span>Terjadwal dalam kalender masjid</span></div></div></section>${v?`<div class="dashboard-section-heading"><div><h2>Amanah zakat & qurban</h2><p>Ringkasan dana khusus · ${dashboardYear}</p></div><button class="link" data-page="laporan">Lihat laporan →</button></div><div class="fund-summary-grid">${fundSummary('zakat',v)}${fundSummary('qurban',v)}</div>${moduleBanner()}<div class="fund-chart-grid">${fundChartPanel('zakat')}${fundChartPanel('qurban')}</div>`:''}<div class="dashboard-section-heading"><div><h2>Aktivitas masjid</h2><p>Arus kas, transaksi terakhir, dan agenda jamaah.</p></div></div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h3>Arus kas umum</h3><p>6 bulan terakhir · terpisah dari zakat & qurban</p></div><button class="link" data-page="keuangan">Detail ↗</button></div>${fin?chart():'<div class="empty">Akses keuangan terbatas.</div>'}</section><section class="panel"><div class="panel-head"><div><h3>Transaksi terbaru</h3><p>Catatan penerimaan dan pengeluaran kas umum</p></div><button class="link" data-page="keuangan">Semua →</button></div>${fin?txTable([...db.finance_transactions].sort((a,b)=>b.occurred_on.localeCompare(a.occurred_on)).slice(0,4)):'<div class="empty">Akses keuangan terbatas.</div>'}</section></div><div><section class="panel"><div class="panel-head"><div><h3>Agenda masjid</h3><p>Bersama dalam kebaikan</p></div><button class="link" data-page="kegiatan">Semua →</button></div>${eventRows(ev.slice(0,3))}</section><section class="panel"><div class="panel-head"><h3>Akses cepat</h3></div><div class="quick">${permitted('finance_transactions')?'<button data-add="finance_transactions"><b>＋</b>Catat transaksi</button>':''}${permitted('events')?'<button data-add="events"><b>▦</b>Buat kegiatan</button>':''}<button data-page="pengaturan"><b>⚙</b>Pengaturan</button></div></section></div></div>`};

// Physical quantities are deliberately kept separate from money.
const fundViews={zakat:'money',qurban:'money'};
const animalLabels={sapi_pribadi:'Sapi Pribadi',sapi_patungan:'Sapi Patungan',kambing:'Kambing',kerbau:'Kerbau',domba:'Domba'};
function animalCounts(year){const counts=Object.fromEntries(Object.keys(animalLabels).map(k=>[k,0]));qurbanAutomatic().qurban_animals.filter(a=>Number(a.year)===Number(year)).forEach(a=>{const k=a.species==='sapi'?(Number(a.capacity)>1?'sapi_patungan':'sapi_pribadi'):a.species;if(k in counts)counts[k]++});return counts}
function physicalFundRows(kind,from,to){return Array.from({length:to-from+1},(_,i)=>{const year=from+i;if(kind==='zakat'){const entries=(db.zakat_entries||[]).filter(r=>Number((r.occurred_on||'').slice(0,4))===year);return {year,riceIn:entries.filter(r=>r.direction==='receipt').reduce((s,r)=>s+(Number(r.rice_kg)||0),0),riceOut:entries.filter(r=>r.direction==='distribution').reduce((s,r)=>s+(Number(r.rice_kg)||0),0)}}return {year,...animalCounts(year),meat:(db.qurban_distribution||[]).filter(r=>Number(r.year)===year&&r.collected_at).reduce((s,r)=>s+(Number(r.weight_kg)||0),0)}})}
const moneyFundChart=fundChart;
fundChart=kind=>{if(fundViews[kind]==='money')return moneyFundChart(kind).replaceAll('Penyaluran dana',kind==='qurban'?'Pengeluaran':'Dana disalurkan');const range=dashboardRanges[kind],rows=physicalFundRows(kind,range.from,range.to),view=fundViews[kind],unit=view==='animals'?'ekor':'kg',series=view==='rice'?[['riceIn','Beras diterima','#3f7e65'],['riceOut','Beras disalurkan','#c4a450']]:view==='meat'?[['meat','Daging tersalurkan','#3f7e65']]:Object.entries(animalLabels).map(([k,l],i)=>[k,l,['#3f7e65','#c4a450','#6a8fac','#a786af','#bf8060'][i]]),values=series.map(([k])=>rows.reduce((s,r)=>s+r[k],0)),max=Math.max(1,...rows.flatMap(r=>series.map(([k])=>r[k]))),format=n=>fmt(n)+' '+unit;
 const svg=`<svg class="fund-svg" viewBox="0 0 600 240" role="img" aria-label="Grafik ${kind} dalam ${unit}. Rincian angka tersedia dalam tabel.">${[0,.5,1].map(v=>`<line x1="58" x2="584" y1="${194-v*162}" y2="${194-v*162}" stroke="#e4e9e1" stroke-dasharray="4 5"/><text x="48" y="${198-v*162}" text-anchor="end">${fmt(max*v)}</text>`).join('')}${rows.map((r,i)=>{const step=526/rows.length,cx=58+step*(i+.5),w=Math.min(23,step*.75/series.length);return `<g>${series.map(([k,l,color],j)=>`<rect x="${cx-w*series.length/2+j*w}" y="${194-r[k]/max*162}" width="${Math.max(1,w-2)}" height="${r[k]/max*162}" rx="2" fill="${color}"><title>${r.year} · ${l}: ${format(r[k])}</title></rect>`).join('')}<text x="${cx}" y="217" text-anchor="middle">${r.year}</text></g>`}).join('')}</svg>`;
 return `<div class="fund-chart-content" aria-live="polite"><div class="fund-chart-totals">${series.map(([k,l,color],i)=>`<div><small><i class="chart-dot" style="background:${color}"></i>${l}</small><strong>${format(values[i])}</strong></div>`).join('')}</div><div class="fund-plot">${values.some(n=>n>0)?svg:'<div class="chart-empty"><span>Belum ada data pada rentang tahun ini</span><p>Pilih rentang tahun lain atau catat data baru.</p></div>'}</div><p class="chart-footnote">${view==='rice'?'Berat beras dari transaksi penerimaan dan penyaluran zakat.':view==='meat'?'Hanya distribusi yang sudah dikonfirmasi diserahkan; alokasi yang belum diserahkan tidak dihitung.':'Hewan terdaftar dari kelompok Shohibul Qurban dan arsip hewan lama. Sapi Patungan dihitung per kelompok maksimal 7 peserta, termasuk kelompok belum penuh. Bukan konfirmasi pembelian atau penyembelihan.'}</p><details class="chart-details"><summary>Lihat rincian per tahun</summary><div class="table-wrap"><table><thead><tr><th>Tahun</th>${series.map(([,l])=>`<th>${l} (${unit})</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${r.year}</td>${series.map(([k])=>`<td>${format(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></div>`;
};
const originalFundPanel=fundChartPanel;
fundChartPanel=kind=>{const views=kind==='zakat'?[['money','Dana (Rp)'],['rice','Beras (kg)']]:[['money','Dana (Rp)'],['animals','Hewan (ekor)'],['meat','Daging (kg)']];return originalFundPanel(kind).replace('ARUS DANA TAHUNAN','REKAP TAHUNAN').replace('Penerimaan & penyaluran '+kind,'Grafik Informasi '+(kind==='zakat'?'Zakat':'Qurban')).replace('<form class="year-range"',`<div class="fund-view-tabs" role="group" aria-label="Jenis grafik ${kind}">${views.map(([k,l])=>`<button type="button" data-fund-kind="${kind}" data-fund-view="${k}" aria-pressed="${fundViews[kind]===k}">${l}</button>`).join('')}</div><form class="year-range"`)};
const originalBindDashboard=bindDashboard;
bindDashboard=()=>{originalBindDashboard();document.querySelectorAll('[data-fund-view]').forEach(b=>b.onclick=()=>{const kind=b.dataset.fundKind;fundViews[kind]=b.dataset.fundView;document.querySelectorAll(`[data-fund-kind="${kind}"]`).forEach(t=>t.setAttribute('aria-pressed',String(t===b)));$('#chart-'+kind).innerHTML=fundChart(kind)})};
fundSummary=(kind,v,year=dashboardYear)=>{const z=kind==='zakat',incoming=z?v.zIn:v.qIn,outgoing=z?v.zOut:v.qOut,counts=z?null:animalCounts(year);return `<section class="fund-summary ${z?'':'qurban-summary-card'}"><div class="fund-summary-top"><span class="fund-icon">${svgIcon(kind)}</span><div><h3>Informasi ${z?'Zakat':'Qurban'}</h3><small>Tahun kegiatan ${year}</small></div><button class="link" data-page="${kind}" aria-label="Buka menu ${kind}">${dashboardArrow}</button></div><div class="fund-balance"><small>Saldo ${z?'dana':'kas'}</small><strong>${money(incoming-outgoing)}</strong></div><div class="fund-split"><div><small>Dana diterima</small><b>${money(incoming)}</b></div><div><small>${z?'Dana disalurkan':'Pengeluaran'}</small><b>${money(outgoing)}</b></div></div>${z?`<div class="physical-metrics"><div><small>Beras diterima</small><strong>${fmt(v.riceIn)} <em>kg</em></strong></div><div><small>Beras disalurkan</small><strong>${fmt(v.riceOut)} <em>kg</em></strong></div><div><small>Sisa beras</small><strong>${fmt(v.riceIn-v.riceOut)} <em>kg</em></strong></div></div>`:`<div class="physical-metrics">${Object.entries(counts).filter(([k,n])=>['sapi_pribadi','sapi_patungan','kambing'].includes(k)||n>0).map(([k,n])=>`<div><small>${animalLabels[k]}</small><strong>${n} <em>ekor</em></strong></div>`).join('')}</div><div class="meat-metric"><span>Daging tersalurkan</span><strong>${fmt(v.kg)} <em>kg</em></strong></div><p class="fund-note">${v.collected}/${v.coupons} distribusi selesai. Hewan terdaftar; sapi patungan per kelompok maksimal 7 peserta, termasuk kelompok belum penuh.</p>`}</section>`};
const informationModulePage=renderModulePage;
renderModulePage=()=>{const html=informationModulePage();if(!allowedModule()||!['zakat','qurban'].includes(page))return html;const container=document.createElement('div');container.innerHTML=html;const stats=container.querySelector('.stats');if(stats){const wrapper=document.createElement('div');wrapper.className='module-information';wrapper.innerHTML=fundSummary(page,totals(season),season);stats.replaceWith(wrapper)}container.insertAdjacentHTML('beforeend',`<div class="module-information-chart">${fundChartPanel(page)}</div>`);return container.innerHTML};

