function isoDay(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function eventsForDay(d){return db.events.filter(e=>isoDay(new Date(e.starts_at))===isoDay(d)&&(calendarFilter==='all'||(calendarFilter==='published'?e.is_published:!e.is_published))).sort((a,b)=>a.starts_at.localeCompare(b.starts_at))}
function eventPill(e){return `<button class="calendar-event ${e.is_published?'published':'draft'}" data-event-detail="${esc(e.id)}" title="${esc(e.title)}"><span>${new Date(e.starts_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</span><strong>${esc(e.title)}</strong></button>`}
function calendarToolbar(){return `<div class="calendar-toolbar"><div class="segmented" aria-label="Tampilan kegiatan"><button data-calendar-view="month" class="${calendarMode==='month'?'selected':''}" aria-pressed="${calendarMode==='month'}">Bulan</button><button data-calendar-view="week" class="${calendarMode==='week'?'selected':''}" aria-pressed="${calendarMode==='week'}">Minggu</button><button data-calendar-view="list" class="${calendarMode==='list'?'selected':''}" aria-pressed="${calendarMode==='list'}">Daftar</button></div>${calendarMode!=='list'?`<div class="calendar-controls"><button class="round-button" data-calendar-step="-1" aria-label="Periode sebelumnya">‹</button><button class="secondary" id="calendar-today">Hari ini</button><button class="round-button" data-calendar-step="1" aria-label="Periode berikutnya">›</button></div>`:''}<div class="calendar-legend"><span><i></i>Dipublikasikan</span><span><i></i>Draf</span></div></div>`}
function calendarMarkup(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),start=new Date(y,m,calendarMode==='week'?calendarDate.getDate():1);start.setDate(start.getDate()-(start.getDay()+6)%7);const count=calendarMode==='week'?7:42,dates=Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return d});const end=dates[dates.length-1];const heading=calendarMode==='week'?`${date(start)} – ${date(end)}`:calendarDate.toLocaleDateString('id-ID',{month:'long',year:'numeric'});const monthEvents=db.events.filter(e=>{const d=new Date(e.starts_at);return d.getMonth()===m&&d.getFullYear()===y});return top('Kalender kegiatan','Satu ruang untuk merencanakan kebaikan bersama.',permitted('events')?'<button class="primary" data-add="events">＋ Kegiatan baru</button>':'')+`<div class="calendar-summary"><span>${svgIcon('kegiatan')}<strong>${monthEvents.length}</strong> Kegiatan bulan ini</span><span><i class="status-dot"></i><strong>${monthEvents.filter(e=>e.is_published).length}</strong> Dipublikasikan</span><span><i class="status-dot gold"></i><strong>${monthEvents.filter(e=>!e.is_published).length}</strong> Draf</span><span class="calendar-demo">${live?'Data masjid aktif':'Data contoh · mode demo'}</span></div>`+calendarToolbar()+`<div class="calendar-layout"><section class="panel calendar-panel"><div class="panel-head"><div><h3>${esc(heading)}</h3><p>Klik agenda untuk melihat detail</p></div><label class="calendar-filter"><select id="calendar-filter" aria-label="Filter status kegiatan"><option value="all">Semua status</option><option value="published" ${calendarFilter==='published'?'selected':''}>Dipublikasikan</option><option value="draft" ${calendarFilter==='draft'?'selected':''}>Draf</option></select></label></div><div class="calendar-scroll"><div class="calendar-grid ${calendarMode==='week'?'week-view':''}">${['SEN','SEL','RAB','KAM','JUM','SAB','MIN'].map(s=>`<div class="weekday">${s}</div>`).join('')}${dates.map(d=>`<div class="calendar-day ${d.getMonth()!==m?'outside':''} ${isoDay(d)===isoDay(new Date())?'is-today':''}"><div class="day-top"><span>${d.getDate()}</span>${permitted('events')?`<button data-calendar-create="${isoDay(d)}" aria-label="Tambah kegiatan ${isoDay(d)}">＋</button>`:''}</div>${eventsForDay(d).map(eventPill).join('')}</div>`).join('')}</div></div></section><div class="calendar-side"><section class="panel"><div class="panel-head"><div><h3>Agenda mendatang</h3><p>Langkah kecil, manfaat besar.</p></div></div><div class="upcoming-events">${db.events.filter(e=>new Date(e.starts_at)>=new Date()).sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).slice(0,5).map(e=>`<button data-event-detail="${esc(e.id)}"><span class="mini-date"><strong>${new Date(e.starts_at).getDate()}</strong><small>${new Date(e.starts_at).toLocaleDateString('id-ID',{month:'short'})}</small></span><span><strong>${esc(e.title)}</strong><small>${e.is_published?'Dipublikasikan':'Draf'} · ${new Date(e.starts_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</small></span><span>↗</span></button>`).join('')||'<div class="empty">Belum ada agenda mendatang.</div>'}</div></section><div class="calendar-message"><span>✦</span><h3>Kebaikan dimulai<br>dari kebersamaan.</h3><p>Rencanakan kegiatan yang membuat jamaah semakin dekat.</p></div></div></div>`}
const dataRender=render;
render=()=>{const previous=uiPreviousPage,previousSection=uiPreviousSection;dataRender();uiPreviousSection=section;if(page==='kegiatan'){if(calendarMode==='list'){$('.page-top').insertAdjacentHTML('afterend',calendarToolbar())}else{$('#main').innerHTML=calendarMarkup();$('#calendar-filter').onchange=e=>{calendarFilter=e.target.value;render()}}}bindDashboard();if(page==='dashboard'){const tag=document.createElement('div');tag.className='dashboard-greeting';tag.textContent='RUANG KELOLA MASJID';$('.page-top > div').prepend(tag)}$('#main').dataset.page=page;$('#breadcrumb').insertAdjacentHTML('beforeend',`<span class="inline-status ${live?'connected':''}">${live?'● Supabase aktif':'● Mode demo'}</span>`);$('#account-panel').hidden=true;$('#profile-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===page;if(b.closest('#nav')||b.closest('.icon-rail')){b.classList.toggle('active',active);active?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current')}});movePill();if(previous===page&&moduleTabs[page]&&previousSection!==section)enterPage($('#module-list')?.closest('.panel'));if(previous!==page){uiPreviousPage=page;window.scrollTo({top:0,behavior:'instant'});enterPage();const active=$('#nav button.active');if(active)$('#nav').scrollTo?.({left:Math.max(0,active.offsetLeft-$('#nav').clientWidth/2+active.offsetWidth/2),behavior:uiMotion.matches?'instant':'smooth'})}};
function uiDialog(title,body){$('#ui-dialog-title').textContent=title;$('#ui-dialog-body').innerHTML=body;$('#ui-dialog').showModal()}
function openSearch(){uiDialog('Jelajahi SIMAS',`<label class="search-label"><input id="menu-search" aria-label="Cari menu SIMAS" placeholder="Cari menu, zakat, kupon…" autocomplete="off"></label><div id="menu-results"></div><p class="dialog-hint">Pilih menu untuk membuka ruang kerja.</p>`);const entries=[...menus.map(([p,n])=>({p,n,t:'Menu utama'})),{p:'pengaturan',n:'Pengaturan & koneksi',t:'Akun dan database'},...Object.entries(tableNames).map(([s,n])=>({p:s.startsWith('zakat')?'zakat':'qurban',s,n,t:'Data dan transaksi'}))];const list=()=>{const q=$('#menu-search').value.toLowerCase();$('#menu-results').innerHTML=entries.filter(x=>(x.n+' '+x.t).toLowerCase().includes(q)).map(x=>`<button data-ui-go="${x.p}" ${x.s?`data-ui-section="${x.s}"`:''}>${svgIcon(x.p)}<span><strong>${esc(x.n)}</strong><small>${x.t}</small></span><span>↗</span></button>`).join('')||'<div class="empty">Menu tidak ditemukan.</div>'};$('#menu-search').oninput=list;list();$('#menu-search').focus()}
function openQuick(){const entries=[['events','Kegiatan baru','kegiatan'],['finance_transactions','Transaksi kas','keuangan'],['assets','Inventaris','inventaris'],['zakat_people','Muzakki / Mustahik','zakat'],['zakat_entries','Transaksi zakat','zakat'],['qurban_people','Peserta qurban','qurban'],['qurban_distribution','Distribusi','qurban']].filter(([t])=>permitted(t));uiDialog('Catat amanah baru',`<p class="dialog-hint">Pilih data yang ingin Anda tambahkan.</p><div class="quick-grid">${entries.map(([t,n,p])=>`<button data-quick-type="${t}">${svgIcon(p)}<strong>${n}</strong><span>Tambah data ↗</span></button>`).join('')||'<p>Peran Anda memiliki akses baca.</p>'}</div>`)}
function openEvent(id){const e=db.events.find(r=>r.id===id);if(!e)return;uiDialog(e.title,`<span class="badge ${e.is_published?'':'expense'}">${e.is_published?'Dipublikasikan':'Draf'}</span><div class="event-detail-time">${svgIcon('kegiatan')}<div><strong>${date(e.starts_at)}</strong><p>${new Date(e.starts_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}${e.ends_at?' — '+esc(new Date(e.ends_at).toLocaleString('id-ID')):''}</p></div></div><p class="event-description">${esc(e.description||'Belum ada deskripsi kegiatan.')}</p>${permitted('events')?`<button class="primary" data-ui-event-edit="${esc(id)}">Edit kegiatan ↗</button>`:''}`)}
$('#global-search').onclick=openSearch;$('#quick-create').onclick=openQuick;$('#ui-dialog-close').onclick=()=>$('#ui-dialog').close();$('#profile-toggle').onclick=()=>{const panel=$('#account-panel');panel.hidden=!panel.hidden;$('#profile-toggle').setAttribute('aria-expanded',String(!panel.hidden))};$('#home-link').onclick=e=>{e.preventDefault();page='dashboard';render();window.scrollTo(0,0)};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#account-panel').hidden=true;$('#profile-toggle').setAttribute('aria-expanded','false')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!$('#modal').open){e.preventDefault();if(!$('#ui-dialog').open)openSearch()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!e.target.closest('.header-right')){$('#account-panel').hidden=true;$('#profile-toggle').setAttribute('aria-expanded','false')}if(!b)return;if(b.dataset.calendarView){calendarMode=b.dataset.calendarView;render();enterPage()}if(b.dataset.calendarStep){const step=Number(b.dataset.calendarStep);if(calendarMode==='week')calendarDate.setDate(calendarDate.getDate()+step*7);else calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+step,1);render();enterPage()}if(b.id==='calendar-today'){calendarDate=new Date();render();enterPage()}if(b.dataset.calendarCreate){showForm('events');$('#form').elements.starts_at.value=b.dataset.calendarCreate+'T08:00'}if(b.dataset.eventDetail)openEvent(b.dataset.eventDetail);if(b.dataset.uiEventEdit){$('#ui-dialog').close();showForm('events',b.dataset.uiEventEdit)}if(b.dataset.uiGo){$('#ui-dialog').close();page=b.dataset.uiGo;if(b.dataset.uiSection)section=b.dataset.uiSection;render();window.scrollTo(0,0)}if(b.dataset.quickType){$('#ui-dialog').close();const t=b.dataset.quickType;if(extraTables.includes(t))fillModuleForm(t);else showForm(t)}});

// Shared letterhead, distribution import and permission-scoped record deletion.
const newCoupon=y=>'Q-'+y+'-'+crypto.randomUUID();
zakatHeaders.qurban_distribution=['Tahun Kegiatan','Nama Penerima','Nama RT','Dusun RT/RW','Berat (kg)'];
const oldTemplate=downloadZakatTemplate;
downloadZakatTemplate=()=>{if(section!=='qurban_distribution')return oldTemplate();downloadBlob(SimasExport.xlsx([{name:'Data',rows:[zakatHeaders.qurban_distribution]},{name:'Petunjuk',rows:[['Kolom','Ketentuan'],['Tahun Kegiatan','Bilangan bulat 2000–2200'],['Nama Penerima','Wajib; minimal 2 karakter'],['Nama RT','Wajib'],['Dusun RT/RW','Wajib; contoh Dusun Krajan RT 01/RW 02'],['Berat (kg)','Angka positif, maksimal 3 desimal; tanpa pemisah ribuan'],['Impor','Isi sheet Data mulai baris 2. Maksimal 1000 baris / 2 MB. Nomor distribusi otomatis. Tidak mengubah data lama.']]}]),'Template-Distribusi-Qurban.xlsx')};
const oldParser=parseZakatRows;
parseZakatRows=(matrix,t)=>{if(t!=='qurban_distribution')return oldParser(matrix,t);const errors=[],records=[],seen=new Set(),str=v=>String(v??'').trim();if(JSON.stringify((matrix[0]||[]).map(str))!==JSON.stringify(zakatHeaders[t]))return {records,errors:['Judul kolom tidak sesuai. Gunakan template Distribusi.']};if(matrix.length>1001)return {records,errors:['Maksimal 1000 baris per impor.']};matrix.slice(1).forEach((a,i)=>{if(a.every(v=>!str(v)))return;try{const d={year:Number(a[0]),recipient:str(a[1]),rt_name:str(a[2]),address:str(a[3]),weight_kg:Number(a[4])};if(a.slice(5).some(v=>str(v)))throw Error('Ada kolom tambahan.');if(!Number.isInteger(d.year)||d.year<2000||d.year>2200)throw Error('Tahun tidak valid.');if(d.recipient.length<2||d.recipient.length>150||!d.rt_name||d.rt_name.length>100||!d.address||d.address.length>500)throw Error('Lengkapi nama penerima, nama RT, dan Dusun RT/RW sesuai batas panjang.');if(!/^\d+(\.\d{1,3})?$/.test(str(a[4]))||!(d.weight_kg>0)||d.weight_kg>999999999)throw Error('Berat harus positif, maksimal 3 desimal.');const key=[d.year,d.recipient,d.rt_name,d.address].join('|').toLowerCase();if(seen.has(key)||db.qurban_distribution.some(r=>[r.year,r.recipient,r.rt_name||'',r.address||''].join('|').toLowerCase()===key))throw Error('Penerima dengan alamat yang sama sudah tercatat pada tahun ini.');seen.add(key);records.push({...d,coupon:newCoupon(d.year)})}catch(err){errors.push('Baris '+(i+2)+': '+err.message)}});if(!records.length&&!errors.length)errors.push('Sheet Data belum berisi data.');return {records,errors}};
const logoSafe=value=>typeof value==='string'&&value.length<=300000&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+=*$/.test(value)?value:'';
function letterheadHTML(){const logo=logoSafe(mosque.logo_data_url);return `<div class="report-letterhead">${logo?`<img src="${logo}" alt="Logo masjid">`:''}<div><h1>${esc(mosque.name)}</h1><p>${esc(mosque.address||'')}${mosque.city?' · '+esc(mosque.city):''}</p>${mosque.phone?`<p>Tel. ${esc(mosque.phone)}</p>`:''}</div></div>`}
function letterheadRows(title){return [[mosque.name],[mosque.address||''],[mosque.city||''],[title],[live?'Data Supabase':'DATA DEMO — BUKAN LAPORAN OPERASIONAL'],[]]}
printDocument=async(title,body)=>{let area=$('#print-area');if(!area){area=document.createElement('section');area.id='print-area';document.body.appendChild(area)}area.innerHTML=letterheadHTML()+`<h2>${esc(title)}</h2>${['zakat','qurban','laporan'].includes(page)?`<p>Tahun rekap: ${season}</p>`:''}<p>${live?'Data Supabase':'DATA DEMO — BUKAN LAPORAN OPERASIONAL'}</p>${body}<p class="print-foot">Dicetak ${new Date().toLocaleString('id-ID')} · SIMAS</p>`;await Promise.all([...area.querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));window.print()};
exportModule=(t,matrix)=>{if(!allowedModule()||moduleError)return toast('Laporan belum tersedia.');const title=(tableNames[t]||'Rekap Zakat Fitrah & Mal')+' · '+season;const sheets=[{name:'Data',rows:[...letterheadRows(title),...matrix]}];if(t==='summary'){const v=totals();sheets.push({name:'Kas Qurban',rows:[...letterheadRows('Kas Qurban · '+season),['Pemasukan',v.qIn],['Pengeluaran',v.qOut],['Saldo',v.qIn-v.qOut],['Distribusi diambil',v.collected],['Total distribusi',v.coupons],['Daging tersalurkan (kg)',v.kg]]})}downloadBlob(SimasExport.xlsx(sheets),'SIMAS-'+t+'-'+season+'.xlsx');toast('✓ Laporan Excel diunduh')};
function coreReport(){const t=mapping[page],q=($('#search')?.value||'').toLowerCase(),kind=$('#filter')?.value;let rows=(db[t]||[]).filter(r=>[r.title,r.name,r.description,r.user_id,r.role].join(' ').toLowerCase().includes(q)&&(!kind||r.kind===kind));if(t==='events')rows=rows.filter(r=>calendarFilter==='all'||(calendarFilter==='published'?r.is_published:!r.is_published));const data={finance_transactions:()=>[['Tanggal','Kategori','Keterangan','Jenis','Nominal (Rp)'],...rows.map(r=>[r.occurred_on,db.finance_categories.find(c=>c.id===r.category_id)?.name||'',r.description,r.kind==='income'?'Pemasukan':'Pengeluaran',Number(r.amount)])],events:()=>[['Kegiatan','Deskripsi','Mulai','Selesai','Status'],...rows.map(r=>[r.title,r.description,date(r.starts_at),r.ends_at?date(r.ends_at):'',r.is_published?'Dipublikasikan':'Draf'])],assets:()=>[['Nama barang','Jumlah','Kondisi','Lokasi'],...rows.map(r=>[r.name,r.quantity,r.condition,r.location])],memberships:()=>[['ID pengguna','Peran'],...rows.map(r=>[r.user_id,r.role])]};return data[t]?.()||[['Data']]}
function chooseCoreExport(){const title=menus.find(m=>m[0]===page)?.[1]||'Laporan',matrix=coreReport();uiDialog('Ekspor '+title,'<p>Data mengikuti pencarian/filter yang aktif. Kop memakai identitas masjid dari Pengaturan.</p><div class="quick-grid"><button id="core-xlsx">Excel (.xlsx)</button><button id="core-pdf">PDF · Cetak / Simpan</button></div>');$('#core-xlsx').onclick=()=>{downloadBlob(SimasExport.xlsx([{name:'Laporan',rows:[...letterheadRows(title),...matrix]}]),'SIMAS-'+title+'.xlsx');$('#ui-dialog').close()};$('#core-pdf').onclick=()=>{$('#ui-dialog').close();printDocument(title,plainTable(matrix))}}
const deletable=['finance_transactions','finance_categories','events','assets','memberships',...extraTables];
function deleteButton(t,id){return `<button class="link danger" data-remove="${t}" data-id="${esc(id)}">Hapus</button>`}
function deletionProblem(t,id){if(t==='memberships'){const r=db.memberships.find(r=>r.user_id===id);if(id===session?.user.id||(!live&&id==='demo-admin'))return 'Keanggotaan akun sendiri tidak dapat dihapus.';if(r?.role==='admin'&&db.memberships.filter(r=>r.role==='admin').length<=1)return 'Admin terakhir tidak dapat dihapus.'}const refs={finance_categories:[['finance_transactions','category_id']],zakat_people:[['zakat_entries','party_id']],qurban_people:[['qurban_shares','person_id'],['qurban_cash','person_id']],qurban_animals:[['qurban_shares','animal_id']]};if((refs[t]||[]).some(([table,key])=>(db[table]||[]).some(r=>r[key]===id)))return 'Data masih digunakan catatan lain. Hapus atau koreksi catatan terkait terlebih dahulu.';return ''}
async function removeRecord(t,id){if(!permitted(t)||!deletable.includes(t))throw Error('Akses ditolak.');const problem=deletionProblem(t,id);if(problem)throw Error(problem);if(live){const key=t==='memberships'?'user_id':'id';const rows=await api('/rest/v1/'+t+'?'+key+'=eq.'+encodeURIComponent(id)+'&mosque_id=eq.'+mosque.id,{method:'DELETE',headers:{Prefer:'return=representation'}});if(!rows?.length)throw Error('Data tidak terhapus. Periksa akses atau muat ulang.');await loadLive()}else{const next={...db,[t]:db[t].filter(r=>(r.id||r.user_id)!==id)};localStorage.setItem('simas-demo',JSON.stringify(next));db=next}}
function confirmDelete(t,id){if(!permitted(t))return;const r=db[t]?.find(r=>(r.id||r.user_id)===id);if(!r)return toast('Data otomatis mengikuti sumber Shohibul Qurban.');const problem=deletionProblem(t,id);if(problem)return toast(problem);uiDialog('Hapus data?',`<p>Hapus <strong>${esc(r.full_name||r.recipient||r.title||r.name||r.description||r.user_id||'catatan ini')}</strong>?</p><p>Penghapusan permanen. Rekap terkait akan dihitung ulang. ${t==='qurban_people'&&r.qurban_category?'Kelompok hewan, pembagian peserta, dan penerimaan otomatis peserta ini juga diperbarui.':''}</p><p id="delete-error" class="error-text" role="alert"></p><div class="action-buttons"><button id="cancel-delete" class="secondary">Batal</button><button id="confirm-delete" class="primary danger">Ya, hapus</button></div>`);$('#cancel-delete').onclick=()=>$('#ui-dialog').close();$('#confirm-delete').onclick=async()=>{const b=$('#confirm-delete');b.disabled=true;try{await removeRecord(t,id);$('#ui-dialog').close();render();toast('✓ Data berhasil dihapus')}catch(err){$('#delete-error').textContent=/foreign key|violates.*constraint/i.test(err.message)?'Data masih digunakan catatan lain. Hapus catatan terkait terlebih dahulu.':err.message;b.disabled=false}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const t=b.dataset.remove||b.dataset.delete;if(t){e.preventDefault();e.stopImmediatePropagation();confirmDelete(t,b.dataset.id)}},true);
const oldShowForm=showForm;showForm=(t,id)=>{oldShowForm(t,id);if(t==='finance_categories'&&id&&$('#modal').open){$('#form').elements.kind.value=db[t].find(r=>r.id===id)?.kind||'income';$('#form').elements.kind.disabled=true}};
const profileSettings=settings;settings=()=>profileSettings()+`<section class="panel settings-panel"><h3>Identitas & kop surat masjid</h3><p>Nama dan alamat digunakan pada semua laporan Excel dan PDF. Logo ditampilkan pada ikon masjid dan kop PDF.</p>${letterheadHTML()}${permitted('mosques')?`<form id="profile-form">${input('name','Nama masjid',mosque.name,'text','required minlength="2" maxlength="150"')}${input('address','Alamat masjid',mosque.address||'','text','required maxlength="500"')}${input('city','Kota / kabupaten',mosque.city||'','text','maxlength="150"')}${input('phone','Telepon',mosque.phone||'','text','maxlength="40"')}<label>Ikon / logo masjid (PNG, JPG, WebP; maksimal 200 KB)<input id="mosque-logo-file" type="file" accept="image/png,image/jpeg,image/webp"></label><div id="logo-preview">${logoSafe(mosque.logo_data_url)?`<img class="logo-preview" src="${logoSafe(mosque.logo_data_url)}" alt="Logo masjid">`:''}</div><label><input type="checkbox" name="remove_logo"> Gunakan ikon bawaan</label><p id="profile-error" class="error-text" role="alert"></p><button class="primary" type="submit">Simpan identitas masjid</button></form>`:'<p>Hanya admin dapat mengubah identitas masjid.</p>'}</section><section class="panel settings-panel"><h3>Pembaruan distribusi, penghapusan & identitas</h3><p>Jalankan pembaruan SQL ini setelah kedua migrasi modul sebelumnya untuk menggunakan fitur pada database Supabase.</p><a class="secondary" href="downloads/20261106_distribution_profile.sql" download>↓ Unduh pembaruan SQL distribusi & profil</a></section>`;
function bindProfile(){const f=$('#profile-form');if(!f)return;let logo=mosque.logo_data_url||'',pending=false,valid=true;$('#mosque-logo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;pending=true;valid=false;$('#profile-error').textContent='';try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>200*1024)throw Error('Gunakan PNG, JPG, atau WebP maksimal 200 KB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Berkas gagal dibaca.'));reader.readAsDataURL(file)});if(!logoSafe(data))throw Error('Format logo tidak valid.');const img=new Image();img.src=data;await img.decode();logo=data;valid=true;$('#logo-preview').innerHTML=`<img class="logo-preview" src="${data}" alt="Pratinjau logo">`}catch(err){$('#profile-error').textContent=err.message}finally{pending=false}};f.onsubmit=async e=>{e.preventDefault();if(pending||(!valid&&!f.elements.remove_logo.checked)){toast('Tunggu logo selesai dibaca atau pilih berkas yang valid.');return}const b=f.querySelector('[type=submit]');b.disabled=true;try{const d=Object.fromEntries(new FormData(f));delete d.remove_logo;for(const k of Object.keys(d))d[k]=d[k].trim();if(d.name.length<2||!d.address)throw Error('Lengkapi nama dan alamat masjid.');d.logo_data_url=f.elements.remove_logo.checked?null:logo||null;await save('mosques',mosque.id,d);render();toast('✓ Identitas dan kop surat diperbarui')}catch(err){$('#profile-error').textContent=err.message}finally{b.disabled=false}}}
function decorateDeletes(){document.querySelectorAll('[data-edit],[data-module-edit]').forEach(b=>{const t=b.dataset.edit||b.dataset.moduleEdit;if(deletable.includes(t)&&permitted(t)&&!b.parentElement.querySelector('[data-delete],[data-remove]'))b.insertAdjacentHTML('afterend',deleteButton(t,b.dataset.id))})}
const profileRender=render;render=()=>{profileRender();const logo=logoSafe(mosque.logo_data_url);$('.workspace-symbol').innerHTML=logo?`<img src="${logo}" alt="Logo masjid">`:'◈';$('#mosque-city').textContent=mosque.address||mosque.city||'Ruang kelola masjid';bindProfile();if(page==='keuangan'&&permitted('finance_categories')){const panel=document.createElement('section');panel.className='panel';panel.innerHTML='<div class="panel-head"><h3>Kategori keuangan</h3></div>'+plainTable([['Nama kategori','Jenis'],...db.finance_categories.map(c=>[c.name,c.kind==='income'?'Pemasukan':'Pengeluaran'])],db.finance_categories.map(c=>actions('finance_categories',c)));$('#main').appendChild(panel)}decorateDeletes();if(mapping[page]&&page!=='pengumuman'&&(page!=='pengurus'||role==='admin')&&(page!=='keuangan'||['admin','takmir','bendahara'].includes(role))){const existing=$('#export');if(existing){existing.textContent='Ekspor ▾';existing.onclick=chooseCoreExport}else{$('.page-top')?.insertAdjacentHTML('beforeend','<button id="core-report" class="secondary">Ekspor ▾</button>');$('#core-report')?.addEventListener('click',chooseCoreExport)}}if(['inventaris','pengurus'].includes(page)){const add=$('.page-top [data-add]'),exp=$('#core-report');if(exp){const group=document.createElement('div');group.className='page-actions';group.setAttribute('role','group');group.setAttribute('aria-label','Aksi '+page);exp.before(group);group.append(exp);if(add)group.append(add)}}};
const listingWithDelete=renderListing;renderListing=()=>{listingWithDelete();decorateDeletes()};
const moduleWithDelete=moduleTable;moduleTable=()=>{moduleWithDelete();decorateDeletes()};
const oldOpenEvent=openEvent;openEvent=id=>{oldOpenEvent(id);const edit=$('[data-ui-event-edit]');if(edit&&permitted('events'))edit.insertAdjacentHTML('afterend',deleteButton('events',id))};

// weight_kg remains the total used by reports, collected totals and dashboard graphs.
function distributionTotal(count,weight){const n=Number(count),w=Number(weight);if(!Number.isInteger(n)||n<1||n>1000000||!Number.isFinite(w)||w<=0||Math.abs(w*1000-Math.round(w*1000))>0.00001)throw Error('Jumlah paket harus bilangan bulat 1–1.000.000; berat per paket harus positif, maksimal 3 desimal.');const total=n*Math.round(w*1000)/1000;if(total>999999999.999)throw Error('Total berat melebihi batas 999.999.999,999 kg.');return total}
function validateDistribution(d){if(!Number.isInteger(Number(d.year))||d.year<2000||d.year>2200)throw Error('Tahun harus 2000–2200.');for(const [k,min,max,label] of [['rt_name',1,100,'Nama RT'],['village',2,200,'Desa/Dusun'],['rt_rw',1,100,'RT/RW']]){const value=String(d[k]??'').trim();if(value.length<min||value.length>max)throw Error(label+' wajib diisi (maksimal '+max+' karakter).')}distributionTotal(d.package_count,d.package_weight_kg)}
function distributionFields(r){return yearField(r)+field('rt_name','Nama RT',r.rt_name||'','text','required maxlength="100"')+field('village','Desa/Dusun',r.village||'','text','required minlength="2" maxlength="200"')+field('rt_rw','RT/RW',r.rt_rw||'','text','required maxlength="100" placeholder="Contoh: RT 01 / RW 02"')+field('package_count','Jumlah Paket',r.package_count??1,'number','required min="1" max="1000000" step="1"')+field('package_weight_kg','Berat per Paket (kg)',r.package_weight_kg??r.weight_kg??2,'number','required min="0.001" max="999999999.999" step="0.001"')+field('weight_kg','Total Berat (kg)',r.weight_kg??2,'number','readonly aria-describedby="distribution-formula"')+'<p id="distribution-formula" class="note" aria-live="polite">Total berat = jumlah paket × berat per paket.</p>'+(!r.village&&r.id?`<p class="note">Arsip lama: ${esc(r.recipient||'')} · ${esc(r.address||'')}. Total lama dipertahankan sebagai 1 paket. Lengkapi Desa/Dusun dan RT/RW saat mengedit.</p>`:'')+`<p class="note">Nomor distribusi dibuat otomatis. ${r.collected_at?'Sudah diserahkan.':''}</p>`}
function bindDistributionForm(f){const update=()=>{try{const total=distributionTotal(f.elements.package_count.value,f.elements.package_weight_kg.value);f.elements.weight_kg.value=total;$('#distribution-formula').textContent=fmt(Number(f.elements.package_count.value))+' paket × '+fmt(Number(f.elements.package_weight_kg.value))+' kg = '+fmt(total)+' kg';}catch(err){f.elements.weight_kg.value='';$('#distribution-formula').textContent=err.message}};f.elements.package_count.oninput=update;f.elements.package_weight_kg.oninput=update;update()}
const distributionReportRows=reportRows;
reportRows=(t,rows=scoped(t))=>t!=='qurban_distribution'?distributionReportRows(t,rows):[['Tahun','Nomor distribusi','Nama RT','Desa/Dusun','RT/RW','Jumlah Paket','Berat per Paket (kg)','Total Berat (kg)','Status','Waktu diambil'],...rows.map(r=>[r.year,r.coupon,r.rt_name||'—',r.village||r.address||'Arsip lama',r.rt_rw||'—',r.package_count??1,Number(r.package_weight_kg??r.weight_kg),Number(r.weight_kg),r.collected_at?'Sudah diambil':'Belum diambil',r.collected_at?new Date(r.collected_at).toLocaleString('id-ID'):'—'])];
