const packageTemplate=downloadZakatTemplate;
downloadZakatTemplate=()=>{if(section!=='qurban_distribution')return packageTemplate();downloadBlob(SimasExport.xlsx([{name:'Data',rows:[zakatHeaders.qurban_distribution]},{name:'Petunjuk',rows:[['Kolom','Ketentuan'],['Tahun Kegiatan','2000–2200'],['Nama RT','Wajib; maksimal 100 karakter'],['Desa/Dusun','Wajib; 2–200 karakter'],['RT/RW','Wajib; maksimal 100 karakter'],['Jumlah Paket','Bilangan bulat positif, maksimal 1000000'],['Berat per Paket (kg)','Positif, maksimal 3 desimal. Contoh 2.5'],['Total Berat (kg)','Boleh dikosongkan: dihitung otomatis. Jika diisi harus sama dengan jumlah paket × berat per paket. Tanpa formula Excel.'],['Contoh','25 paket × 2.5 kg = 62.5 kg'],['Impor','Maksimal 1000 baris / 2 MB. Template lama tidak berlaku; unduh template terbaru.']]}]),'Template-Distribusi-Qurban.xlsx')};
const packageParser=parseZakatRows;
parseZakatRows=(matrix,t)=>{if(t!=='qurban_distribution')return packageParser(matrix,t);const records=[],errors=[],seen=new Set(),str=v=>String(v??'').trim();if(JSON.stringify((matrix[0]||[]).map(str))!==JSON.stringify(zakatHeaders[t]))return {records,errors:['Kolom tidak sesuai. Unduh template Distribusi terbaru (jumlah paket dan berat per paket).']};if(matrix.length>1001)return {records,errors:['Maksimal 1000 baris per impor.']};matrix.slice(1).forEach((a,i)=>{if(a.every(v=>!str(v)))return;try{const d={year:Number(a[0]),rt_name:str(a[1]),village:str(a[2]),rt_rw:str(a[3]),package_count:Number(a[4]),package_weight_kg:Number(a[5])};if(a.slice(7).some(v=>str(v)))throw Error('Ada kolom tambahan.');validateDistribution(d);d.weight_kg=distributionTotal(d.package_count,d.package_weight_kg);if(str(a[6])&&(!Number.isFinite(Number(a[6]))||Math.abs(Number(a[6])-d.weight_kg)>0.000001))throw Error('Total berat tidak sama dengan jumlah paket × berat per paket.');const key=JSON.stringify(d);if(seen.has(key)||db.qurban_distribution.some(r=>Object.keys(d).every(k=>String(r[k]??'')===String(d[k]??''))))throw Error('Distribusi identik sudah tercatat.');seen.add(key);records.push({...d,coupon:newCoupon(d.year)})}catch(err){errors.push('Baris '+(i+2)+': '+err.message)}});if(!records.length&&!errors.length)errors.push('Sheet Data belum berisi data.');return {records,errors}};
const packagesSettings=settings;
settings=()=>packagesSettings()+`<section class="panel settings-panel"><h3>Pembaruan distribusi per paket</h3><p>Jalankan SQL ini setelah pembaruan distribusi & profil. Total data lama tetap dipertahankan. Database menghitung total berat dari jumlah paket × berat per paket.</p><a class="secondary" href="downloads/20261110_distribution_packages.sql" download>↓ Unduh SQL distribusi per paket</a></section>`;

